import React from 'react';
import { FilterValue } from './App';

type TodolistProps = {
    title: string
    tasks: Task[]
    removeTask: (taskId: string) => void
    filterForTask: (value: FilterValue) => void
}

export type Task = {
    id: string
    title: string
    isDone: boolean
}



export const Todolist = (props: TodolistProps) => {

    const tasks = props.tasks.map((task: Task) => (
        <li key={task.id}>
            <input type="checkbox" checked={task.isDone} />
            <span>{task.title}</span>
            <button onClick={() => { props.removeTask(task.id) }}>X</button>
        </li>
    ))

    return (
        <div>
            <h3>{props.title}</h3>
            <div>
                <input />
                <button>+</button>
            </div>
            <ul>
                {tasks}
            </ul>
            <div>
                <button onClick={() => { props.filterForTask('all') }}>All</button>
                <button onClick={() => { props.filterForTask('active') }}>Active</button>
                <button onClick={() => { props.filterForTask('completed') }}>Completed</button>
            </div>
        </div>
    )
}
